$root = Split-Path -Parent $PSScriptRoot; $out = Join-Path $root 'research\smoke_tests\prepilot-fix-20260819'; New-Item -ItemType Directory -Force -Path $out | Out-Null
$cases = @(
  @{id='red-ginseng'; question='What are the traditional TCM properties, meridian associations, and traditional uses of Red Ginseng (Hongshen)?'; conditions=@('C1','C2')},
  @{id='liver-yang'; question='What does the TCM Research Corpus record about liver yang?'; conditions=@('C1','C2')},
  @{id='multi-target'; question='How are Red Ginseng and deficiency of the kidney-yang represented in the TCM corpus, and what evidence is recorded for each?'; conditions=@('C1','C2')}
)
$agents=@('syndrome','herbal','acupuncture_meridian','constitution','dietary_therapy','lifestyle_yangsheng'); $judges=@('evidence','hallucination','safety','conflict','confidence','provenance'); $results=@()
foreach($case in $cases){foreach($condition in $case.conditions){$payload=@{question=$case.question;condition_id=$condition;retrieval_strategy='R0';active_agents=$agents;active_judges=$judges;top_k=4;debate_rounds=1;include_trace=$true}|ConvertTo-Json -Depth 8; $sw=[Diagnostics.Stopwatch]::StartNew(); try{$data=Invoke-RestMethod -Method Post -Uri 'http://127.0.0.1:8002/api/research/run' -ContentType 'application/json' -Body $payload -TimeoutSec 180;$sw.Stop();$trace=$data.trace;$attempted=[int]$trace.provider_calls;$succeeded=[int]$trace.successful_provider_calls;$evidence=@($data.retrieval);$ids=@($evidence|% chunk_id);$class=if($trace.generation_mode -eq 'abstention' -and !$evidence.Count){'FAIL_ROUTING'}elseif($trace.generation_mode -eq 'llm' -and !$trace.fallback_usage){if($attempted -gt $succeeded){'PASS_WITH_RETRY'}else{'PASS'}}elseif($trace.fallback_usage){'FAIL_PROVIDER'}else{'FAIL_OUTPUT_QUALITY'};$rec=[ordered]@{case_id=$case.id;condition=$condition;question=$case.question;run_id=$data.run_id;classification=$class;generation_mode=$trace.generation_mode;fallback=[bool]$trace.fallback_usage;corpus=$trace.corpus_name;chunk_count=$trace.corpus_chunk_count;provider=$trace.provider;model=$trace.model;provider_attempted=$attempted;provider_succeeded=$succeeded;latency_ms=$trace.latency_ms;participating_agents=(@($trace.participating_agents)-join ';');abstaining_agents=(@($trace.abstaining_agents)-join ';');evidence_ids=($ids -join ';');answer=$data.final_answer;trace=$trace}}catch{$sw.Stop();$rec=[ordered]@{case_id=$case.id;condition=$condition;question=$case.question;classification='FAIL_PROVIDER';error=$_.Exception.Message;client_latency_ms=[int]$sw.ElapsedMilliseconds}};$results+=[pscustomobject]$rec;Write-Host "$($case.id) $condition $($rec.classification) $($rec.latency_ms)ms"}}
$results|ConvertTo-Json -Depth 15|Set-Content (Join-Path $out 'results.json') -Encoding UTF8
$results|Select-Object case_id,condition,classification,generation_mode,fallback,corpus,chunk_count,provider,model,provider_attempted,provider_succeeded,latency_ms,participating_agents,abstaining_agents,evidence_ids|Export-Csv (Join-Path $out 'summary.csv') -NoTypeInformation -Encoding UTF8
